import os
import re
import sys

import pytest

from click.shell_completion import CompletionItem
from click.testing import CliRunner


@pytest.fixture
def runner():
    return CliRunner()


@pytest.fixture
def isolated_cli_runner(runner):
    with runner.isolated_filesystem():
        yield runner


@pytest.mark.parametrize(
    ("shell", "expected_output"),
    [
        (
            "zsh",
            """\
_foo_completion () {
  local reply
  local completions
  local word="${1}"
  local completions_src=( $( env _FOO_COMPLETE=zsh_complete "${word}" ) )
  while IFS= read -r line; do
    completions+=( "${line}" )
  done < <(printf "%s\\n" "${completions_src[@]}")
  _describe 'values' reply "${completions[@]}"
}
compdef _foo_completion foo
""",
        ),
    ],
)
def test_completion_script(isolated_cli_runner, shell, expected_output):
    with open("foo.py", "w") as f:
        f.write(
            """#!/usr/bin/env python3
from click.shell_completion import CompletionItem
import click

class Foo(click.ParamType):
    def convert(self, value, param, ctx):
        return value

    def shell_complete(self, ctx, param, incomplete):
        return [
            CompletionItem(value=value, help="adsf") for value in
            ["baz:quux", "spam:eggs"]
        ]

@click.command()
@click.argument("foo", type=Foo())
def main(foo):
    print(foo)
"""
        )
    result = isolated_cli_runner.run(
        [sys.executable, "foo.py"],
        env={f"_FOO_COMPLETE": f"{shell}_source"},
    )
    assert not result.exception
    assert result.output == expected_output


@pytest.mark.parametrize(
    ("shell", "incomplete", "expected_output"),
    [
        ("zsh", "", "baz:quux:adsf\nspam:eggs:adsf\n"),
        ("zsh", "b", "baz:quux:adsf\n"),
        ("zsh", "s", "spam:eggs:adsf\n"),
    ],
)
def test_completion(isolated_cli_runner, shell, incomplete, expected_output):
    with open("foo.py", "w") as f:
        f.write(
            """#!/usr/bin/env python3
from click.shell_completion import CompletionItem
import click

class Foo(click.ParamType):
    def convert(self, value, param, ctx):
        return value

    def shell_complete(self, ctx, param, incomplete):
        return [
            CompletionItem(value=value, help="adsf") for value in
            ["baz:quux", "spam:eggs"]
            if value.startswith(incomplete)
        ]

@click.command()
@click.argument("foo", type=Foo())
def main(foo):
    print(foo)
"""
        )
    result = isolated_cli_runner.run(
        [sys.executable, "foo.py", incomplete],
        env={f"_FOO_COMPLETE": f"{shell}_complete"},
    )
    assert not result.exception
    assert result.output == expected_output

